/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type WealthGrowthChartProps = Record<string, any>;

const WealthGrowthChart: React.FC<WealthGrowthChartProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "Business Success Rate",
  primaryColor = "#00e5ff",
  dangerColor = "#ff3366",
  gridColor = "#334155",
  particleCount = 35,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Dimensions for 9:16
  const chartWidth = 800;
  const chartHeight = 900;
  const startX = 140; 
  const startY = 550; 

  const mapX = (year: number) => ((year - 2000) / 26) * chartWidth;
  const mapY = (val: number) => chartHeight - (val / 100) * chartHeight;

  // Path Data Generators
  const linePoints: string[] = [];
  const resolution = 100;

  for (let i = 0; i <= resolution; i++) {
    const year = 2000 + (i / resolution) * 26;
    const x = mapX(year);
    const val = interpolate(year, [2000, 2010, 2020, 2026], [100, 69, 51, 35], {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    });
    linePoints.push(`${x},${mapY(val)}`);
  }

  const path = `M ${linePoints.join(" L ")}`;
  const areaPath = `${path} L ${chartWidth},${chartHeight} L 0,${chartHeight} Z`;

  // Animation Timings
  const wipeStartFrame = 45;
  const wipeEndFrame = durationInSeconds * fps - 60;
  const wipeProgress = interpolate(
    frame,
    [wipeStartFrame, wipeEndFrame],
    [0, chartWidth],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic Leading Node Logic
  const currentYear = 2000 + (wipeProgress / chartWidth) * 26;
  const currentVal = interpolate(currentYear, [2000, 2010, 2020, 2026], [100, 69, 51, 35], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const currentY = mapY(currentVal);
  const isDanger = currentVal < 50;
  const currentNodeColor = isDanger ? dangerColor : primaryColor;

  // Labels
  const yLabels = [
    { label: "100%", value: 100 },
    { label: "75%", value: 75 },
    { label: "50%", value: 50 },
    { label: "25%", value: 25 },
    { label: "0%", value: 0 },
  ];
  const xLabels = [2000, 2010, 2020, 2026];

  // Camera & Holographic Effects
  const pushInScale = interpolate(frame, [0, durationInSeconds * fps], [0.95, 1.05]);
  const translateY = interpolate(frame, [0, durationInSeconds * fps], [20, -20]);
  const titleOpacity = interpolate(frame, [0, 10, 15, 20], [0, 0.5, 0.2, 1], { extrapolateRight: "clamp" });
  
  const chartRotationX = interpolate(frame, [0, durationInSeconds * fps], [15, 5]);
  const chartRotationY = interpolate(frame, [0, durationInSeconds * fps], [-8, 0]);

  const bokehParticles = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => ({
      x: random(`x-${i}`) * 120 - 10,
      y: random(`y-${i}`) * 120 - 10,
      size: random(`s-${i}`) * 100 + 20,
      opacity: random(`o-${i}`) * 0.15 + 0.05,
      speed: random(`sp-${i}`) * 0.8 + 0.2,
    }));
  }, [particleCount]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Volumetric Radial Light */}
      <div
        style={{
          position: "absolute",
          top: "-20%",
          left: "-20%",
          width: "140%",
          height: "140%",
          background: `radial-gradient(circle at ${interpolate(frame, [0, durationInSeconds * fps], [40, 60])}% ${interpolate(frame, [0, durationInSeconds * fps], [30, 70])}%, rgba(0, 229, 255, 0.15) 0%, rgba(0, 0, 0, 0) 50%)`,
          opacity: interpolate(frame, [0, 30], [0, 1]),
        }}
      />

      {/* Bokeh Particles */}
      <div style={{ position: "absolute", width: "100%", height: "100%" }}>
        {bokehParticles.map((p, i) => {
          const yPos = p.y - frame * p.speed;
          const op = p.opacity * interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" });
          return (
            <div
              key={`bokeh-${i}`}
              style={{
                position: "absolute",
                left: `${p.x}%`,
                top: `${yPos}%`,
                width: p.size,
                height: p.size,
                borderRadius: "50%",
                backgroundColor: primaryColor,
                filter: "blur(30px)",
                opacity: op,
              }}
            />
          );
        })}
      </div>

      <AbsoluteFill style={{ transform: `scale(${pushInScale}) translateY(${translateY}px)` }}>
        {/* Titles & Legends */}
        <div style={{ position: "absolute", top: 150, left: 0, width: "100%", display: "flex", flexDirection: "column", alignItems: "center" }}>
          <h1
            style={{
              fontFamily: interFamily,
              fontSize: 56,
              color: "#ffffff",
              margin: 0,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              textShadow: `0 0 20px rgba(255,255,255,0.3)`,
              opacity: titleOpacity,
            }}
          >
            {title}
          </h1>

          <div style={{ display: "flex", gap: 30, marginTop: 40, opacity: titleOpacity }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div 
                style={{ 
                  width: 16, 
                  height: 16, 
                  borderRadius: "50%", 
                  background: `linear-gradient(to bottom, ${primaryColor} 50%, ${dangerColor} 50%)`, 
                  boxShadow: `0 0 12px ${primaryColor}` 
                }} 
              />
              <span style={{ fontFamily: interFamily, fontSize: 24, color: "#f8fafc", fontWeight: 500 }}>Active Businesses Over Time</span>
            </div>
          </div>
        </div>

        {/* 3D Floating Chart Environment */}
        <div
          style={{
            position: "absolute",
            left: startX,
            top: startY,
            width: chartWidth,
            height: chartHeight,
            transformStyle: "preserve-3d",
            perspective: "1200px",
            transform: `rotateX(${chartRotationX}deg) rotateY(${chartRotationY}deg)`,
          }}
        >
          {/* Layer 1: Grid & Axes */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(-50px)" }}>
            {yLabels.map((lbl, i) => {
              const y = mapY(lbl.value);
              const lineOpacity = interpolate(frame, [15 + i * 5, 30 + i * 5], [0, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              const textOpacity = interpolate(frame, [15 + i * 5, 30 + i * 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              
              // Emphasize the 50% threshold line slightly
              const isThreshold = lbl.value === 50;

              return (
                <g key={`y-${i}`}>
                  <line 
                    x1={0} 
                    y1={y} 
                    x2={chartWidth} 
                    y2={y} 
                    stroke={isThreshold ? dangerColor : gridColor} 
                    strokeDasharray="6 6" 
                    strokeWidth={isThreshold ? 3 : 2} 
                    opacity={lineOpacity} 
                  />
                  <text x={-20} y={y + 8} fill={isThreshold ? dangerColor : "#94a3b8"} fontSize={24} fontFamily={robotoMonoFamily} textAnchor="end" opacity={textOpacity}>{lbl.label}</text>
                </g>
              );
            })}
            {xLabels.map((val, i) => {
              const x = mapX(val);
              const opacity = interpolate(frame, [30 + i * 5, 45 + i * 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              return (
                <g key={`x-${i}`}>
                  <line x1={x} y1={0} x2={x} y2={chartHeight} stroke={gridColor} strokeDasharray="6 6" strokeWidth={1.5} opacity={opacity * 0.2} />
                  <text x={x} y={chartHeight + 45} fill="#94a3b8" fontSize={24} fontFamily={robotoMonoFamily} textAnchor="middle" opacity={opacity}>{val}</text>
                </g>
              );
            })}
            <text x={chartWidth / 2} y={chartHeight + 100} fill="#64748b" fontSize={24} fontFamily={interFamily} textAnchor="middle" opacity={interpolate(frame, [50, 65], [0, 1], { extrapolateLeft: "clamp" })}>
              Year
            </text>
          </svg>

          {/* Layer 2: Area Fills */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(-20px)" }}>
            <defs>
              <clipPath id="wipeClip">
                <rect x={-20} y={-50} width={wipeProgress + 20} height={chartHeight + 100} />
              </clipPath>
              <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2={chartHeight} gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor={primaryColor} stopOpacity={0.25} />
                <stop offset="50%" stopColor={primaryColor} stopOpacity={0.05} />
                <stop offset="50%" stopColor={dangerColor} stopOpacity={0.05} />
                <stop offset="100%" stopColor={dangerColor} stopOpacity={0.25} />
              </linearGradient>
            </defs>
            <path d={areaPath} fill="url(#areaGrad)" clipPath="url(#wipeClip)" />
          </svg>

          {/* Layer 3: Data Lines */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(10px)" }}>
            <defs>
              <filter id="lineGlow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="12" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
              <linearGradient id="lineGrad" x1="0" y1="0" x2="0" y2={chartHeight} gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor={primaryColor} />
                <stop offset="50%" stopColor={primaryColor} />
                <stop offset="50%" stopColor={dangerColor} />
                <stop offset="100%" stopColor={dangerColor} />
              </linearGradient>
            </defs>
            <path 
              d={path} 
              fill="none" 
              stroke="url(#lineGrad)" 
              strokeWidth={6} 
              strokeLinecap="round" 
              strokeLinejoin="round" 
              clipPath="url(#wipeClip)" 
              filter="url(#lineGlow)" 
            />
          </svg>

          {/* Layer 4: Glowing Nodes & Highlights */}
          <svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible", transform: "translateZ(40px)" }}>
            <defs>
              <filter id="nodeGlow" x="-100%" y="-100%" width="300%" height="300%">
                <feGaussianBlur stdDeviation="8" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>

            {/* Static Nodes tracking data milestones */}
            {xLabels.map((val, i) => {
              const nodeX = mapX(val);
              const nodeVal = interpolate(val, [2000, 2010, 2020, 2026], [100, 69, 51, 35], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
              const nodeY = mapY(nodeVal);
              const passedProgress = interpolate(wipeProgress, [nodeX - 5, nodeX + 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              
              if (passedProgress === 0) return null;
              
              const isNodeDanger = nodeVal < 50;
              const nodeColor = isNodeDanger ? dangerColor : primaryColor;
              
              return (
                <circle
                  key={`static-node-${i}`}
                  cx={nodeX}
                  cy={nodeY}
                  r={8 * passedProgress}
                  fill={backgroundColor}
                  stroke={nodeColor}
                  strokeWidth={3 * passedProgress}
                  filter="url(#nodeGlow)"
                  opacity={passedProgress}
                />
              );
            })}

            {/* Leading Node */}
            {frame >= wipeStartFrame && wipeProgress < chartWidth && (
              <circle
                cx={wipeProgress}
                cy={currentY}
                r={10}
                fill="#ffffff"
                stroke={currentNodeColor}
                strokeWidth={5}
                filter="url(#nodeGlow)"
              />
            )}
          </svg>
        </div>
      </AbsoluteFill>

      {/* Holographic Scanlines Overlay */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          background: `repeating-linear-gradient(
            0deg,
            transparent,
            transparent 4px,
            rgba(255, 255, 255, 0.015) 4px,
            rgba(255, 255, 255, 0.015) 8px
          )`,
          opacity: interpolate(frame, [0, 20], [0, 1]),
          pointerEvents: "none",
          mixBlendMode: "screen",
        }}
      />
    </AbsoluteFill>
  );
};

export default WealthGrowthChart;